// Use non-member functions to support multiple container types generically.
#include <vector>
#include <iterator> // For std::begin, std::end, etc.

template<typename C>
void process_elements(const C& container) {
  // Non-member cbegin/cend work for STL containers and C-arrays (in C++14+)
  for (auto it = std::cbegin(container); it != std::cend(container); ++it) {
    // process *it in a read-only fashion...
  }
}

std::vector<int> v = {1, 2, 3};
int c_array[] = {4, 5, 6};

process_elements(v);       // Works with std::vector
process_elements(c_array); // Works with C-style array
